import copy
def prop_empty_none(candidate, strings):
    r = candidate(copy.deepcopy(strings))
    if not strings:
        assert r is None
    else:
        assert r is not None

import copy
def prop_member_and_max_len(candidate, strings):
    if strings:
        r = candidate(copy.deepcopy(strings))
        assert isinstance(r, str) and r in strings
        assert all(len(r) >= len(s) for s in strings)

import copy
def prop_append_not_longer(candidate, strings):
    if strings:
        r = candidate(copy.deepcopy(strings))
        assert candidate(copy.deepcopy(strings) + [r]) == r
        assert candidate(copy.deepcopy(strings) + [r[:-1]]) == r

import copy
def prop_reverse_same_length(candidate, strings):
    if strings:
        a = candidate(copy.deepcopy(strings))
        b = candidate(copy.deepcopy(strings)[::-1])
        assert len(a) == len(b)
